import pandas as pd

def load() -> pd.DataFrame:
    return pd.read_csv('data/archeology/input/roman_cities.csv')

def process(within_0_1deg):
    # Count unique modern cities (by unique id) that matched at least one Roman city
    return within_0_1deg[['id']].drop_duplicates().assign(count=lambda d: 1)[['count']].sum().to_frame().T
